selector_to_html = {"a[href=\"#stage-scoped-environment-manager-flenvmanager\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Stage-Scoped Environment Manager (FLEnvManager)<a class=\"headerlink\" href=\"#stage-scoped-environment-manager-flenvmanager\" title=\"Link to this heading\">#</a></h2><p>RL post-training has different operator-acceleration and communication requirements in the training stage and the rollout stage. The environment manager manages FlagGems and FlagCX configuration per stage:</p>", "a[href=\"#features\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Features<a class=\"headerlink\" href=\"#features\" title=\"Link to this heading\">#</a></h1><h2>Hardware-Agnostic Platform Abstraction<a class=\"headerlink\" href=\"#hardware-agnostic-platform-abstraction\" title=\"Link to this heading\">#</a></h2><p>Through the unified <code class=\"docutils literal notranslate\"><span class=\"pre\">PlatformBase</span></code> interface, hardware-specific logic for device management, collective communication, memory management, profiling, and rollout environment variables is abstracted into standard methods. A vendor only needs to implement one platform class and register it with <code class=\"docutils literal notranslate\"><span class=\"pre\">@PlatformRegistry.register</span></code> to integrate with verl.</p><p>For CUDA-compatible hardware such as MetaX and Iluvatar, <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.cuda.is_available()</span></code> returns True on multiple chips. The platform layer introduces a <code class=\"docutils literal notranslate\"><span class=\"pre\">vendor_name</span></code> identifier and SMI-based hardware detection (for example <code class=\"docutils literal notranslate\"><span class=\"pre\">mx-smi</span></code> for MetaX and <code class=\"docutils literal notranslate\"><span class=\"pre\">ixsmi</span></code> for Iluvatar) to distinguish the actual hardware during first-time auto-detection and avoid mismatching the NVIDIA engine.</p>", "a[href=\"#dedicated-flagos-engines-for-fsdp-and-megatron\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Dedicated FlagOS Engines for FSDP and Megatron<a class=\"headerlink\" href=\"#dedicated-flagos-engines-for-fsdp-and-megatron\" title=\"Link to this heading\">#</a></h2><p>FlagOS-specific engines are derived from verl\u2019s native FSDP and Megatron engines, covering the key roles in RL training:</p>", "a[href=\"#hardware-agnostic-platform-abstraction\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Hardware-Agnostic Platform Abstraction<a class=\"headerlink\" href=\"#hardware-agnostic-platform-abstraction\" title=\"Link to this heading\">#</a></h2><p>Through the unified <code class=\"docutils literal notranslate\"><span class=\"pre\">PlatformBase</span></code> interface, hardware-specific logic for device management, collective communication, memory management, profiling, and rollout environment variables is abstracted into standard methods. A vendor only needs to implement one platform class and register it with <code class=\"docutils literal notranslate\"><span class=\"pre\">@PlatformRegistry.register</span></code> to integrate with verl.</p><p>For CUDA-compatible hardware such as MetaX and Iluvatar, <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.cuda.is_available()</span></code> returns True on multiple chips. The platform layer introduces a <code class=\"docutils literal notranslate\"><span class=\"pre\">vendor_name</span></code> identifier and SMI-based hardware detection (for example <code class=\"docutils literal notranslate\"><span class=\"pre\">mx-smi</span></code> for MetaX and <code class=\"docutils literal notranslate\"><span class=\"pre\">ixsmi</span></code> for Iluvatar) to distinguish the actual hardware during first-time auto-detection and avoid mismatching the NVIDIA engine.</p>", "a[href=\"#zero-configuration-plugin-discovery\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Zero-Configuration Plugin Discovery<a class=\"headerlink\" href=\"#zero-configuration-plugin-discovery\" title=\"Link to this heading\">#</a></h2><p>The plugin is discovered by verl through Python\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">entry_points</span></code> mechanism. After <code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span> <span class=\"pre\">install</span></code>, verl imports the package registered under the <code class=\"docutils literal notranslate\"><span class=\"pre\">verl.plugins</span></code> group, which triggers registration of all platforms and engines. No changes to the verl main framework are required.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
